71	    /** The claims of the ids on the sheet in list order: the people in the order they were added,
72	     *  each person's claims newest first; ids not on the sheet are left out. */
73	    @Transactional(readOnly = true)
74	    public List<Long> inListOrder(String sheetId, Collection<Long> ids) {
75	        Set<Long> wanted = new HashSet<>(ids);
76	        Map<Long, Integer> personOrder = new HashMap<>();
77	        List<Person> theirs = people.findBySheetIdOrderByIdAsc(sheetId);
78	        for (int i = 0; i < theirs.size(); i++) {
79	            personOrder.put(theirs.get(i).getId(), i);
80	        }
81	        return claims.findBySheetIdOrderByListedDesc(sheetId).stream()
82	                .filter(c -> wanted.contains(c.getId()))
83	                .sorted(Comparator.comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
84	                .map(Claim::getId)
85	                .toList();
86	    }
87	
88	    /** Add a claim for a person on the sheet; a missing date takes the sheet's today. Refused
89	     *  (423) when the date is in a closed period, (422) when it is after the person's
90	     *  retirement date, and (422) when it is a correction (a negative amount) that does not name
91	     *  the number of a SETTLED claim of the same person. */
92	    @Transactional
93	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
94	            String corrects) {
95	        Person person = people.findByIdAndSheetId(personId, sheetId)
96	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
97	        LocalDate on = date != null ? date : sheets.today(sheetId);
98	        refuseIfClosed(sheetId, on);
99	        refuseIfRetired(person, on);
100	        String corrected = correctedBy(sheetId, personId, amount, corrects);
101	        RollupService.Snapshot before = rollup.snapshot(sheetId);
102	        int terms = sheets.find(sheetId).map(s -> s.termsFor(person.gradeOn(on))).orElse(Sheet.DEFAULT_TERMS);
103	        Claim fresh = new Claim(sheetId, personId, amount, on, on.plusDays(terms), noteOf(note));
104	        fresh.setCorrects(corrected);
105	        // the sheet is locked (refuseIfClosed), so two claims added at once are listed one after the other
106	        fresh.setListed(claims.findLastListed(sheetId) + 1);
107	        Claim claim = claims.saveAndFlush(fresh);
108	        record("CLAIM_ADDED", user, person, claim);
109	        rollup.recordChanges(sheetId, user, before);
110	        return claim;
111	    }
112	
113	    /** Change a DRAFT claim's amount, date and note; a missing date takes the sheet's today.
114	     *  Refused (409) once the claim is no longer a DRAFT (an open claim is voided and a new one
115	     *  added instead), and (423) when its old or new date is in a closed period, and (422) when the new
116	     *  date is after the person's retirement date, or when it is a correction that does not name
117	     *  the number of a SETTLED claim of the same person. */
118	    @Transactional
119	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
120	            String corrects) {
121	        Claim claim = claims.findForUpdate(id, sheetId)
122	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
123	        LocalDate on = date != null ? date : sheets.today(sheetId);
124	        refuseIfClosed(sheetId, claim.getDate());
125	        if (claim.getStatus() != ClaimStatus.DRAFT) {
126	            throw new ResponseStatusException(HttpStatus.CONFLICT,
127	                    "A " + claim.getStatus() + " claim cannot be edited");
128	        }
129	        refuseIfClosed(sheetId, on);
130	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
131	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
132	        refuseIfRetired(person, on);
133	        String corrected = correctedBy(sheetId, person.getId(), amount, corrects);
134	        RollupService.Snapshot before = rollup.snapshot(sheetId);
135	        claim.setAmount(amount);
136	        claim.setCorrects(corrected);
137	        claim.setDate(on);
138	        claim.setNote(noteOf(note));
139	        claims.flush();
140	        record("CLAIM_EDITED", user, person, claim);
141	        rollup.recordChanges(sheetId, user, before);
142	        return claim;
143	    }
144	
145	    /** Move a claim to a new status; a move its status does not allow is refused (409), as is
146	     *  settling by the user who opened the claim (403), settling a PENDING claim (409: it is
147	     *  approved or rejected instead), and any move of a claim dated in a closed period (423). A
148	     *  clerk settling a claim whose due is above the sheet's clerk limit sends it to PENDING. */
149	    @Transactional
150	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus to) {
151	        Claim claim = claims.findForUpdate(id, sheetId)
152	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
153	        refuseIfClosed(sheetId, claim.getDate());
154	        if (to == ClaimStatus.PENDING || (to == ClaimStatus.SETTLED && claim.getStatus() == ClaimStatus.PENDING)
155	                || !claim.getStatus().canMoveTo(to)) {
156	            throw new ResponseStatusException(HttpStatus.CONFLICT,
157	                    "A " + claim.getStatus() + " claim cannot become " + to);
158	        }
159	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
160	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
161	                    "The user who opened a claim cannot settle it");
162	        }
163	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
164	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
165	        // a claim bound by a statement settles at its bound figure, its late charge frozen in
166	        BigDecimal settling = to == ClaimStatus.SETTLED ? shownDueOf(claim, person) : null;
167	        if (to == ClaimStatus.SETTLED && !settings.maySettle(sheetId, user, settling)) {
168	            // above the clerk limit: a steward approves or rejects it
169	            to = ClaimStatus.PENDING;
170	        }
171	        RollupService.Snapshot before = rollup.snapshot(sheetId);
172	        // a voided claim keeps its number (never reused), and the VOIDED record carries it
173	        String number = claim.getNumber();
174	        claim.setStatus(to);
175	        if (to == ClaimStatus.OPEN) {
176	            number = nextNumber(sheetId, claim.getDate());
177	            claim.setNumber(number);
178	            claim.setOpenedBy(user);
179	        } else if (to == ClaimStatus.SETTLED) {
180	            claim.setSettledDue(settling);
181	        }
182	        claims.flush();
183	        String event = switch (to) {
184	            case OPEN -> "CLAIM_OPENED";
185	            case PENDING -> "CLAIM_PENDING";
186	            case SETTLED -> "CLAIM_SETTLED";
187	            case VOID -> "CLAIM_VOIDED";
188	            case DRAFT -> throw new IllegalArgumentException("A claim cannot return to DRAFT");
189	        };
190	        if (to == ClaimStatus.SETTLED) {
191	            record(event, user, person, claim, number, " due=" + dueText(claim.getSettledDue()));
192	        } else {
193	            record(event, user, person, claim, number);
194	        }
195	        rollup.recordChanges(sheetId, user, before);
196	        return claim;
197	    }
198	
199	    /** A steward approves a PENDING claim: it becomes SETTLED, its due (its live figure, with its
200	     *  late charge) frozen now. Refused (409) unless PENDING, (403) for a clerk or the user who
201	     *  opened it, and (423) when it is dated in a closed period. */
202	    @Transactional
203	    public Claim approve(String sheetId, String user, long id) {
204	        Claim claim = pendingForSteward(sheetId, user, id);
205	        if (user.equals(claim.getOpenedBy())) {
206	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
207	                    "The user who opened a claim cannot approve it");
208	        }
209	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
210	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
211	        RollupService.Snapshot before = rollup.snapshot(sheetId);
212	        BigDecimal due = shownDueOf(claim, person);
213	        claim.setStatus(ClaimStatus.SETTLED);
214	        claim.setSettledDue(due);
215	        claims.flush();
216	        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), " due=" + dueText(due));
217	        rollup.recordChanges(sheetId, user, before);
218	        return claim;
219	    }
220	
221	    /** A steward rejects a PENDING claim with a reason: it goes back to OPEN, bound again by the
222	     *  person's last statement if that statement bound it. Refused (409) unless PENDING, (403) for
223	     *  a clerk, and (423) when it is dated in a closed period. */
224	    @Transactional
225	    public Claim reject(String sheetId, String user, long id, String reason) {
226	        Claim claim = pendingForSteward(sheetId, user, id);
227	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
228	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
229	        RollupService.Snapshot before = rollup.snapshot(sheetId);
230	        claim.setStatus(ClaimStatus.OPEN);
231	        claims.flush();
232	        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), " reason=" + reason);
233	        rollup.recordChanges(sheetId, user, before);
234	        return claim;
235	    }
236	
237	    /** A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet: it keeps its
238	     *  number and date, is listed as the new person's newest claim, and loses any figure a
239	     *  statement bound it to (live again until the new person's next statement). Refused (404)
240	     *  when the claim or person is missing, (423) when it is dated in a closed period, (403) for a
241	     *  clerk, (409) when SETTLED or VOID or already the person's, and (422) when it is dated after
242	     *  the new person's retirement date. */
243	    @Transactional
244	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
245	        Claim claim = claims.findForUpdate(id, sheetId)
246	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
247	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
248	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
249	        refuseIfClosed(sheetId, claim.getDate());
250	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
251	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward reassigns a claim");
252	        }
253	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
254	            throw new ResponseStatusException(HttpStatus.CONFLICT,
255	                    "A " + claim.getStatus() + " claim cannot be reassigned");
256	        }
257	        if (claim.getPersonId() == toPersonId) {
258	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already that person's");
259	        }
260	        refuseIfRetired(to, claim.getDate());
261	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
262	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
263	        RollupService.Snapshot before = rollup.snapshot(sheetId);
264	        claim.setPersonId(to.getId());
265	        claim.unbind();
266	        claim.setListed(claims.findLastListed(sheetId) + 1);
267	        claims.flush();
268	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(),
269	                " from=" + from.getName() + " to=" + to.getName());
270	        rollup.recordChanges(sheetId, user, before);
271	        return claim;
272	    }
273	
274	    /** The PENDING claim a steward decides on: refused (404) when missing, (423) when dated in a
275	     *  closed period, (409) unless PENDING, and (403) when the user is not a steward. */
276	    private Claim pendingForSteward(String sheetId, String user, long id) {
277	        Claim claim = claims.findForUpdate(id, sheetId)
278	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
279	        refuseIfClosed(sheetId, claim.getDate());
280	        if (claim.getStatus() != ClaimStatus.PENDING) {
281	            throw new ResponseStatusException(HttpStatus.CONFLICT,
282	                    "Only a PENDING claim is approved or rejected, not a " + claim.getStatus() + " one");
283	        }
284	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
285	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
286	                    "Only a steward approves or rejects a PENDING claim");
287	        }
288	        return claim;
289	    }
290	
291	    private static String dueText(BigDecimal due) {
292	        return due == null ? "n/a" : due.toPlainString();
293	    }
294	
295	    /** Take a statement of a person: record their due-total now, and bind each of their claims
296	     *  that counts (OPEN, PENDING or SETTLED, of a held person only SETTLED) to its figure now; the others
297	     *  are left unbound. */
298	    @Transactional
299	    public Statement statement(String sheetId, String user, long personId) {
300	        Person person = people.findForUpdate(personId, sheetId)
301	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
302	        LocalDate today = sheets.today(sheetId);
303	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
304	        RollupService.Snapshot before = rollup.snapshot(sheetId);
305	        List<Claim> counted = theirs.stream().filter(c -> counts(c, person)).toList();
306	        BigDecimal dueTotal = dueTotalOf(counted, person, today);
307	        for (Claim c : theirs) {
308	            if (counts(c, person)) {
309	                // the statement binds the figure; the late charge keeps following the sheet's today
310	                c.bind(c.getSettledDue() != null ? c.getSettledDue() : figureOf(c, person));
311	            } else {
312	                c.unbind();
313	            }
314	        }
315	        claims.flush();
316	        statements.saveAndFlush(new PersonStatement(sheetId, personId, dueTotal, counted.size(), today, user));
317	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
318	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted.size());
319	        rollup.recordChanges(sheetId, user, before);
320	        return new Statement(person, StatementSummary.of(statements.findByPersonIdOrderByIdAsc(personId)), theirs);
321	    }
322	
323	    /** The number a claim dated {@code date} takes as it is opened: under period numbering (set,
324	     *  and the sheet's today on or after it) the next within the period containing the date
325	     *  (<period name>-<n>), or X-<n> when none does; otherwise the sheet's next number. */
326	    private String nextNumber(String sheetId, LocalDate date) {
327	        if (!sheets.periodNumberingOn(sheetId)) {
328	            return String.valueOf(sheets.nextClaimNumber(sheetId));
329	        }
330	        // held until the transaction ends, so two claims opened at once are numbered one after the other
331	        sheets.lock(sheetId);
332	        String prefix = periods.containing(sheetId, date).map(Period::getName).orElse(NO_PERIOD) + "-";
333	        int last = claims.findNumbers(sheetId).stream()
334	                .filter(n -> n.startsWith(prefix))
335	                .map(n -> n.substring(prefix.length()))
336	                .filter(n -> n.matches("\\d{1,9}"))
337	                .mapToInt(Integer::parseInt)
338	                .max().orElse(0);
339	        return prefix + (last + 1);
340	    }
341	
342	    /** Refuse (423) a change to a claim dated in a closed period, holding the sheet locked until
343	     *  the transaction ends so a period cannot be closed meanwhile. */
344	    private void refuseIfClosed(String sheetId, LocalDate date) {
345	        sheets.lock(sheetId);
346	        periods.refuseIfClosed(sheetId, date);
347	    }
348	
349	    /** The number a claim of the amount corrects: none unless the amount is negative, when it must
350	     *  be the number of a SETTLED claim of the same person, or the claim is refused (422). */
351	    private String correctedBy(String sheetId, long personId, BigDecimal amount, String corrects) {
352	        if (amount.signum() >= 0) {
353	            return null;
354	        }
355	        if (corrects == null
356	                || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
357	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
358	                    "A negative amount must correct a settled claim of the same person");
359	        }
360	        return corrects;
361	    }
362	
363	    /** Refuse (422) a claim dated after its person's retirement date. */
364	    private static void refuseIfRetired(Person person, LocalDate date) {
365	        if (person.retiredBefore(date)) {
366	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
367	                    "The date is after the person's retirement date");
368	        }
369	    }
370	
371	    /** Whether a claim counts toward claimed and due totals: only OPEN (or PENDING) and SETTLED ones
372	     *  do, and of a held person only SETTLED ones. */
373	    private static boolean counts(Claim c, Person person) {
374	        return c.getStatus() == ClaimStatus.SETTLED
375	                || (c.getStatus().isOpen() && !person.isHeld());
376	    }
377	
378	    /** The due a claim shows: the due fixed when it was settled, else its figure with its late
379	     *  charge on top. */
380	    private BigDecimal shownDueOf(Claim claim, Person person) {
381	        if (claim.getSettledDue() != null) {
382	            return claim.getSettledDue();
383	        }
384	        return LateCharge.of(sheets.find(claim.getSheetId())).addTo(claim, figureOf(claim, person), roundingOf(claim));
385	    }
386	
387	    /** A claim's figure before any late charge: the one a statement bound it to (null: n/a), else
388	     *  (unbound, or PENDING) its live due. */
389	    private BigDecimal figureOf(Claim claim, Person person) {
390	        return claim.isBound() ? claim.getStatedDue() : dueOf(claim, person);
391	    }
392	
393	    /** A person's due-total: the sum of the dues their counting claims show (n/a ones skipped);
394	     *  null (n/a) when their grade in force on the sheet's today has no rate then, unless a claim
395	     *  shows a due (a fixed or bound one, or one at the rate of the grade they had on its date). */
396	    private BigDecimal dueTotalOf(List<Claim> counted, Person person, LocalDate today) {
397	        List<BigDecimal> dues = counted.stream().map(c -> shownDueOf(c, person)).filter(d -> d != null).toList();
398	        if (rates.findInForce(person.getSheetId(), person.gradeOn(today), today).isEmpty() && dues.isEmpty()) {
399	            return null;
400	        }
401	        return dues.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
402	    }
403	
404	    /** The claim's amount times the rate, in force on the claim's date, of its person's grade then, divided by
405	     *  100, rounded as its rounding policy has it, raised to the sheet's floor (a correction's never is); null with no rate in force then. */
406	    private BigDecimal dueOf(Claim claim, Person person) {
407	        BigDecimal floor = sheets.floor(claim.getSheetId());
408	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
409	                .map(Rate::getPct)
410	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, roundingOf(claim)))
411	                .map(due -> claim.isCorrection() ? due : due.max(floor))
412	                .orElse(null);
413	    }
414	
415	    /** How the claim's live figures round: by the sheet's policy date against its date, or for a
416	     *  correction the date of the claim it corrects. */
417	    private RoundingMode roundingOf(Claim claim) {
418	        LocalDate on = claim.getCorrects() == null ? claim.getDate()
419	                : claims.findFirstBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
420	                        .map(Claim::getDate).orElse(claim.getDate());
421	        return Rounding.of(sheets.find(claim.getSheetId())).on(on);
422	    }
423	
424	    private void record(String event, String user, Person person, Claim claim) {
425	        record(event, user, person, claim, claim.getNumber());
426	    }
427	
428	    /** Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd. */
429	    private void record(String event, String user, Person person, Claim claim, String number) {
430	        record(event, user, person, claim, number, "");
431	    }
432	
433	    private void record(String event, String user, Person person, Claim claim, String number, String extra) {
434	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
435	                + " person=" + person.getName() + " amount=" + claim.getAmount().setScale(2).toPlainString()
436	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
437	    }
438	
439	    private static String noteOf(String note) {
440	        return note == null ? "" : note.trim();
441	    }
442	}
