    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select c from Claim c where c.personId = :personId and c.sheetId = :sheetId order by c.listed desc")
    List<Claim> findByPersonForUpdate(Long personId, String sheetId);
}
